import { Simulation } from '../core/simulation.js';
const assert = (ok, message) => {
    if (!ok)
        throw new Error(message);
};
const sim = new Simulation({ seed: 240919, hz: 60, benchmark: true });
sim.spawnElite();
const elite = sim.ents.find((e) => e.kind === 'elite');
assert(elite, 'failed to spawn elite');
elite.rarity = 'uplifted';
const record = sim.eliteLogById.get(elite.id);
record.rarity = 'uplifted';
elite.hp = 0;
sim.cleanup();
const drop = sim.pickups.find((p) => p.kind === 'mutation');
assert(drop, 'uplifted elite did not drop a Mutation Core');
assert(sim.mutationCores === 0, 'Mutation Core should not be granted before pickup');
sim.px = drop.x;
sim.pz = drop.z;
sim.updatePickups();
assert(sim.mutationCores === 1, 'Mutation Core pickup did not reach run inventory');
const common = new Simulation({ seed: 240920, hz: 60, benchmark: true });
common.spawnElite();
const commonElite = common.ents.find((e) => e.kind === 'elite');
assert(commonElite, 'failed to spawn common test elite');
commonElite.rarity = 'common';
common.eliteLogById.get(commonElite.id).rarity = 'common';
commonElite.hp = 0;
common.cleanup();
assert(!common.pickups.some((p) => p.kind === 'mutation'), 'common elite dropped a Mutation Core');
console.log('mutation-source-regression OK', { upliftedDrop: true, commonDrop: false });
